function Data-Metadata {
 $roots=@("$env:USERPROFILE/.mesh-talk","$env:APPDATA/com.mesh-talk.desktop","$env:LOCALAPPDATA/com.mesh-talk.desktop")
 foreach($r in $roots){if(Test-Path $r){$files=@(Get-ChildItem $r -Recurse -File -ErrorAction Stop);@{root=$r;files=$files.Count;bytes=($files|Measure-Object Length -Sum).Sum;keystores=@($files|Where-Object {$_.Name -like '*keystore*'}|Select-Object FullName,Length,CreationTimeUtc,LastWriteTimeUtc)}}}
