Data-Metadata|ConvertTo-Json -Depth 5|Set-Content "$w/evidence/windows-data-before.json"
$action=New-ScheduledTaskAction -Execute powershell.exe -Argument "-NoProfile -ExecutionPolicy Bypass -File `"$w/tray.ps1`" -Mode Quit -ExpectedPid 16880 -ExpectedStartTimeUtc `"$($p.StartTime.ToUniversalTime().ToString('o'))`""
