L268:     Some(
L269:       stdout
L270:         .split('\n')
L271:         .map(|t| {
L272:           let mut s = t.split(' ');
L273:           let name = s.next().unwrap().to_string();
L274:           let installed = s.next().map(|v| v == "(installed)").unwrap_or_default();
L275:           RustupTarget { name, installed }
L276:         })
L277:         .filter(|t| !t.name.is_empty())
L278:         .collect(),
L279:     )
